<?php
declare(strict_types=1);
namespace Tests\Unit\QuestionLearning;
use App\Application\QuestionLearning\DTO\Request\UpdateQuestionInteractionRequestDto;use App\Application\QuestionLearning\Mapper\QuestionInteractionResponseMapper;use App\Application\QuestionLearning\Service\UpdateQuestionInteractionService;use App\Domain\QuestionBank\ReadModel\PublishedQuestion;use App\Domain\QuestionBank\ReadModel\PublishedQuestionOption;use App\Domain\QuestionBank\Repository\FrozenQuestionReaderInterface;use App\Domain\QuestionLearning\Entity\LearningEvent;use App\Domain\QuestionLearning\Entity\UserQuestionInteraction;use App\Domain\QuestionLearning\Repository\CompletedAttemptLearningSignalReaderInterface;use App\Domain\QuestionLearning\Repository\LearningEventRepositoryInterface;use App\Domain\QuestionLearning\Repository\UserQuestionInteractionRepositoryInterface;use App\Domain\QuestionLearning\ValueObject\CompletedAttemptLearningSignal;use PHPUnit\Framework\TestCase;
final class UpdateQuestionInteractionSignalTest extends TestCase { public function testRecordsDistinctNonMasteredEventOnlyOnChange(): void { $interactions=new class implements UserQuestionInteractionRepositoryInterface { public ?UserQuestionInteraction $value=null;public function find(string $u,string $q):?UserQuestionInteraction{return $this->value;}public function save(UserQuestionInteraction $v):void{$this->value=$v;} };$events=new class implements LearningEventRepositoryInterface { public array $events=[];public function append(LearningEvent $event):void{$this->events[]=$event;}public function listForUserSubject(string $u,string $s,\DateTimeImmutable $since):array{return [];} };$questions=new class implements FrozenQuestionReaderInterface { public function findByIds(array $ids):array{return [new PublishedQuestion('question-1','', 'EASY',null,null,[new PublishedQuestionOption('option-1','A','',1)])];} };$subjects=new class implements CompletedAttemptLearningSignalReaderInterface { public function read(string $q,string $o,int $e,string $r):?CompletedAttemptLearningSignal{return null;} public function taxonomySubjectIdsForQuestion(string $q):array{return ['subject-1'];} };$service=new UpdateQuestionInteractionService($questions,$interactions,new QuestionInteractionResponseMapper(),$subjects,$events);$service->execute('user-1',new UpdateQuestionInteractionRequestDto('question-1',notMastered:true),new \DateTimeImmutable());$service->execute('user-1',new UpdateQuestionInteractionRequestDto('question-1',notMastered:true),new \DateTimeImmutable());self::assertCount(1,$events->events);self::assertSame('NOT_MASTERED_ENABLED',$events->events[0]->type->value); } }
